# Save unique species
unique = []
seen = set()
for s in all_species:
    n = s['name'].lower()
    if n not in seen:
        seen.add(n)
        unique.append(s)

with open(json_path, 'w', encoding='utf-8') as f:
    json.dump(unique, f, indent=2)

print(f"Total unique species saved: {len(unique)}")
